// Get all merged items from the Merge Node
const allRows = $input.all().map(item => item.json);

// Object to store consolidated balances
const consolidated = {};

allRows.forEach(row => {
  const account = row['Account Name'] || row['Account'] || row['AccountName'];
  const balance = parseFloat(row['Balance'] || row['Amount'] || 0);

  if (!account) return;

  if (!consolidated[account]) {
    consolidated[account] = {
      account_name: account,
      account_type: row['Account Type'] || row['Type'] || '',
      consolidated_balance: 0
    };
  }

  consolidated[account].consolidated_balance += balance;
});

// Intercompany Elimination Logic ($8,000 AR / AP Adjustment)
if (consolidated['Intercompany AR']) {
  consolidated['Intercompany AR'].consolidated_balance = 0;
}
if (consolidated['Intercompany AP']) {
  consolidated['Intercompany AP'].consolidated_balance = 0;
}

// Return as formatted array for Sheet and Summary Nodes
return Object.values(consolidated).map(acc => ({ json: acc }));

const items = $input.all().map(i => i.json);

// Extract Balance Values
let revenue = 0, cogs = 0, salary = 0, rent = 0, utilities = 0;
let cash = 0, ar = 0, inventory = 0, equipment = 0;
let ap = 0, loan = 0, shareCapital = 0;

items.forEach(row => {
  const code = String(row['Account Code']).trim();
  const debit = parseFloat(row.Debit || 0);
  const credit = parseFloat(row.Credit || 0);

  if (code === '4000') revenue = credit;
  if (code === '5000') cogs = debit;
  if (code === '6000') salary = debit;
  if (code === '6100') rent = debit;
  if (code === '6200') utilities = debit;

  if (code === '1001') cash = debit;
  if (code === '1100') ar = debit;
  if (code === '1200') inventory = debit;
  if (code === '1500') equipment = debit;
  if (code === '2000') ap = credit;
  if (code === '2100') loan = credit;
  if (code === '3000') shareCapital = credit;
});

// P&L Calculations
const grossProfit = revenue - cogs;
const totalOpex = salary + rent + utilities;
const netProfit = grossProfit - totalOpex;

// Balance Sheet Calculations
const totalCurrentAssets = cash + ar + inventory;
const totalNonCurrentAssets = equipment;
const totalAssets = totalCurrentAssets + totalNonCurrentAssets;

const totalLiabilities = ap + loan;
const totalEquity = shareCapital + netProfit; // Retained Earnings = Net Profit
const totalLiabilitiesAndEquity = totalLiabilities + totalEquity;

return [{
  json: {
    // Income Statement Metrics
    revenue,
    cogs,
    grossProfit,
    salary,
    rent,
    utilities,
    totalOpex,
    netProfit,

    // Balance Sheet Metrics
    cash,
    ar,
    inventory,
    totalCurrentAssets,
    equipment,
    totalAssets,
    ap,
    loan,
    totalLiabilities,
    shareCapital,
    totalEquity,
    totalLiabilitiesAndEquity,

    // Balance Check
    isBalanced: totalAssets === totalLiabilitiesAndEquity
  }
}];

