// Function to convert basic Markdown to clean HTML
function markdownToHtml(md) {
  if (!md) return '';
  return md
    .replace(/^### (.*$)/gim, '<h3 style="color: #1a365d; border-bottom: 2px solid #e2e8f0; padding-bottom: 5px; margin-top: 20px;">$1</h3>')
    .replace(/^#### (.*$)/gim, '<h4 style="color: #2b6cb0; margin-top: 15px; margin-bottom: 5px;">$1</h4>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/^\* (.*$)/gim, '<li style="margin-bottom: 6px;">$1</li>')
    .replace(/\n\n/g, '<p style="line-height: 1.6; color: #2d3748;"></p>')
    .replace(/\n/g, '<br>');
}

const rawMarkdown = $input.first().json.content.parts[0].text;
const htmlContent = markdownToHtml(rawMarkdown);

// Executive Styled HTML Template
const finalEmailHtml = `
  <div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 700px; margin: 0 auto; padding: 25px; border: 1px solid #e2e8f0; border-radius: 8px; background-color: #ffffff;">
    <div style="background-color: #0f172a; padding: 20px; border-radius: 6px; text-align: center; margin-bottom: 20px;">
      <h2 style="color: #ffffff; margin: 0; font-weight: 600; letter-spacing: 0.5px;">CONSOLIDATED FINANCIAL REPORT</h2>
      <p style="color: #94a3b8; margin: 5px 0 0 0; font-size: 13px;">Group Financial Controller / CFO Statement</p>
    </div>
    <div style="padding: 10px 5px;">
      ${htmlContent}
    </div>
    <div style="margin-top: 30px; padding-top: 15px; border-top: 1px solid #e2e8f0; text-align: center; font-size: 12px; color: #64748b;">
      <p>This is an automated executive summary generated by the Financial Reporting Engine.</p>
    </div>
  </div>
`;

return [{ json: { emailHtml: finalEmailHtml } }];
